package hjdarnel.compassquickviews;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum CameraDirection
{
	NORTH("Look North"),
	EAST("Look East"),
	SOUTH("Look South"),
	WEST("Look West");

	private final String option;

	/**
	 * Gets the direction for a compass menu option, or null if it isn't one.
	 */
	public static CameraDirection fromOption(String option)
	{
		for (CameraDirection direction : values())
		{
			if (direction.option.equals(option))
			{
				return direction;
			}
		}
		return null;
	}
}

package hjdarnel.compassquickviews;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Units;

@ConfigGroup("compass-quick-views")
public interface CompassQuickViewsConfig extends Config
{
	@ConfigItem(
		keyName = "rotationOrder",
		name = "Rotation order",
		description = "The order of the directions the camera rotates through when the compass is clicked repeatedly",
		position = 0
	)
	default RotationOrder rotationOrder()
	{
		return RotationOrder.NORTH_SOUTH_EAST_WEST;
	}

	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "clickWindow",
		name = "Click window",
		description = "The maximum time between clicks for a click to move to the next direction. A slower click goes back to the first direction",
		position = 1
	)
	default int clickWindow()
	{
		return 500;
	}
}

package hjdarnel.compassquickviews;

import com.google.inject.Provides;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.Menu;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Compass Quick Views",
	description = "Quickly click on the compass to rotate through North/South/East/West views, or other configured order",
	tags = {"compass", "camera"}
)
public class CompassQuickViewsPlugin extends Plugin
{
	// The compass is a different component in each interface layout
	private static final Set<Integer> COMPASS_COMPONENTS = Set.of(
		InterfaceID.Toplevel.COMPASSCLICK,
		InterfaceID.ToplevelOsrsStretch.COMPASSCLICK,
		InterfaceID.ToplevelPreEoc.COMPASSCLICK,
		InterfaceID.ToplevelOsm.COMPASSCLICK,
		InterfaceID.OrbsOsmNomap.COMPASSCLICK
	);

	@Inject
	private Client client;

	@Inject
	private CompassQuickViewsConfig config;

	private CameraDirection lastDirection;
	private long lastClickNanos;

	// Intentionally run before other menu swappers, so their custom swaps on the compass take precedence over this one
	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		// Shift-clicks aren't part of the run of clicks, so they keep the compass's normal left-click
		if (isShiftHeld())
		{
			return;
		}

		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();
		if (entries.length == 0 || !isCompass(entries[entries.length - 1].getParam1()))
		{
			return;
		}

		String option = nextDirection().getOption();
		for (int i = entries.length - 1; i >= 0; --i)
		{
			MenuEntry entry = entries[i];
			if (isCompass(entry.getParam1()) && option.equals(Text.removeTags(entry.getOption())))
			{
				entries[i] = entries[entries.length - 1];
				entries[entries.length - 1] = entry;
				menu.setMenuEntries(entries);
				return;
			}
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		// Picking an option from the right-click menu or shift-clicking doesn't continue the run of clicks
		if (client.isMenuOpen() || isShiftHeld() || !isCompass(event.getParam1()))
		{
			return;
		}

		CameraDirection direction = CameraDirection.fromOption(Text.removeTags(event.getMenuOption()));
		if (direction != null)
		{
			lastDirection = direction;
			lastClickNanos = System.nanoTime();
		}
	}

	private CameraDirection nextDirection()
	{
		boolean inWindow = System.nanoTime() - lastClickNanos <= TimeUnit.MILLISECONDS.toNanos(config.clickWindow());
		return config.rotationOrder().next(inWindow ? lastDirection : null);
	}

	private boolean isShiftHeld()
	{
		return client.isKeyPressed(KeyCode.KC_SHIFT);
	}

	private static boolean isCompass(int param1)
	{
		return COMPASS_COMPONENTS.contains(param1);
	}

	@Provides
	CompassQuickViewsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CompassQuickViewsConfig.class);
	}
}

package hjdarnel.compassquickviews;

import static hjdarnel.compassquickviews.CameraDirection.EAST;
import static hjdarnel.compassquickviews.CameraDirection.NORTH;
import static hjdarnel.compassquickviews.CameraDirection.SOUTH;
import static hjdarnel.compassquickviews.CameraDirection.WEST;
import java.util.Arrays;
import java.util.List;

public enum RotationOrder
{
	NORTH_SOUTH_EAST_WEST("North/South/East/West", NORTH, SOUTH, EAST, WEST),
	NORTH_EAST_SOUTH_WEST("North/East/South/West", NORTH, EAST, SOUTH, WEST),
	NORTH_WEST_SOUTH_EAST("North/West/South/East", NORTH, WEST, SOUTH, EAST);

	private final String label;
	private final List<CameraDirection> directions;

	RotationOrder(String label, CameraDirection... directions)
	{
		this.label = label;
		this.directions = Arrays.asList(directions);
	}

	/**
	 * Gets the direction that follows previous in this order, wrapping around at the end.
	 * A null previous direction gives the first direction in the order.
	 */
	public CameraDirection next(CameraDirection previous)
	{
		return directions.get((directions.indexOf(previous) + 1) % directions.size());
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package hjdarnel.compassquickviews;

